// Regenerate src/lib/monaco-entry.ts from the installed monaco-editor.
//
//   node scripts/gen-monaco-entry.mjs
//
// Run this after every monaco bump. It takes monaco's own esm/vs/index.js and
// strips the language SERVICES (css/html/json/typescript) plus the LSP client,
// keeping the editor and every language tokenizer. See the generated file's own
// header for why.
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const root = new URL('../', import.meta.url)
const src = fileURLToPath(new URL('node_modules/monaco-editor/esm/vs/index.js', root))
const dst = fileURLToPath(new URL('src/lib/monaco-entry.ts', root))

const kept = []
for (const line of readFileSync(src, 'utf8').split(/\r?\n/)) {
  if (!line.trim()) continue
  if (line.includes('monaco-lsp-client')) continue
  // ...and the re-export that names what those imports bound.
  if (line.startsWith('export { index as lsp }')) continue
  if (line.includes('languages/features/')) continue
  if (line.startsWith('export { __src_languages_features')) continue
  kept.push(line.replaceAll("'./", "'monaco-vs/"))
}

if (!kept.some((l) => l.startsWith('export {'))) {
  throw new Error('monaco index.js has no re-export line - the layout changed, check by hand')
}

const header = `// GENERATED by scripts/gen-monaco-entry.mjs - do not hand-edit.
//
// This is monaco-editor's own esm/vs/index.js with the language SERVICES and
// the LSP client removed.
//
// Why not import 'monaco-editor' directly: its entry registers the css, html,
// json and typescript language services, and Vite then emits their web workers
// - 8.9 MB of them, 6.7 of which is the TypeScript compiler. All of that would
// live inside paddock.exe forever to give IntelliSense inside a side panel. We
// keep the editor and every language TOKENIZER (highlighting, main thread,
// free) and drop the services, which leaves the small base worker as the only
// one shipped.
//
// Paths go through the \`monaco-vs\` alias (vite.config.ts + tsconfig paths):
// monaco's exports map rewrites deep specifiers and cannot express these.

`

writeFileSync(dst, header + kept.join('\n') + '\n')
console.log(`wrote ${dst} (${kept.length} lines)`)
